1	"use client";
2	
3	import { useEffect, useState } from "react";
4	import Link from "next/link";
5	import { getHostingEmailStatus, setupHostingEmail } from "@/lib/hosting-email";
6	import type { HostingAccountView } from "@/lib/actions-hosting";
7	import { Badge } from "@/components/ui/primitives";
8	
9	type Status = {
10	  planName?: string;
11	  primaryDomain?: string;
12	  includedMailboxes?: number;
13	  hasSubscription?: boolean;
14	  subscriptionId?: string;
15	  verified?: boolean;
16	  error?: string;
17	};
18	
19	/**
20	 * Bundled hosting email. Reuses the audited /dashboard/email UI for the actual
21	 * mailbox management + DNS verification — this tab only kicks off the
22	 * complimentary subscription (setupHostingEmail) and then links across. It never
23	 * lists or provisions mailboxes itself.
24	 */
25	export function EmailTab({ account }: { account: HostingAccountView }) {
26	  const [status, setStatus] = useState<Status | null>(null);
27	  const [busy, setBusy] = useState(false);
28	  const [err, setErr] = useState<string | null>(null);
29	
30	  function refresh() {
31	    getHostingEmailStatus(account.id)
32	      .then((s) => setStatus(s))
33	      .catch(() => setStatus({ error: "Couldn’t load email status." }));
34	  }
35	
36	  useEffect(() => {
37	    refresh();
38	    // eslint-disable-next-line react-hooks/exhaustive-deps
39	  }, [account.id]);
40	
41	  async function setup() {
42	    setBusy(true);
43	    setErr(null);
44	    const r = await setupHostingEmail(account.id);
45	    setBusy(false);
46	    if (r.error) { setErr(r.error); return; }
47	    refresh();
48	  }
49	
50	  if (!status) {
51	    return <div className="card py-12 text-center text-sm text-slate-400">Loading email…</div>;
52	  }
53	  if (status.error) {
54	    return <div className="card py-12 text-center text-sm text-red-300">{status.error}</div>;
55	  }
56	
57	  const count = status.includedMailboxes ?? 0;
58	  const mailboxWord = count === 1 ? "mailbox" : "mailboxes";
59	
60	  return (
61	    <div className="space-y-6">
62	      <div className="card">
63	        <div className="mb-4 flex items-center justify-between gap-2">
64	          <h2 className="font-semibold">Email</h2>
65	          {status.hasSubscription && (
66	            <Badge tone={status.verified ? "green" : "amber"}>
67	              {status.verified ? "Active" : "Verify DNS"}
68	            </Badge>
69	          )}
70	        </div>
71	
72	        <p className="text-sm text-slate-300">
73	          Your <span className="font-medium text-white">{status.planName}</span> plan includes{" "}
74	          <span className="font-medium text-white">{count} {mailboxWord}</span> on{" "}
75	          <span className="font-mono text-slate-200">{status.primaryDomain}</span> — professional
76	          you@yourdomain email at no extra cost.
77	        </p>
78	
79	        {!status.hasSubscription ? (
80	          <>
81	            <p className="mt-3 text-sm text-slate-400">
82	              Set up email to claim your included {mailboxWord}. You’ll then add addresses and
83	              publish the DNS records that route mail to Nxeon.
84	            </p>
85	            {err && <div className="card mt-4 border-red-500/30 text-sm text-red-300">{err}</div>}
86	            <button type="button" className="btn-primary mt-4" disabled={busy} onClick={setup}>
87	              {busy ? "Setting up…" : "Set up my email"}
88	            </button>
89	          </>
90	        ) : (
91	          <>
92	            <p className="mt-3 text-sm text-slate-400">
93	              {status.verified
94	                ? "Your domain is verified. Add and manage mailboxes from the email dashboard."
95	                : "Almost there — add your mailboxes and publish the DNS records shown on the email dashboard to start receiving mail."}
96	            </p>
97	            <Link href="/dashboard/email" className="btn-primary mt-4 inline-block">
98	              Manage mailboxes →
99	            </Link>
100	          </>
101	        )}
102	      </div>
103	    </div>
104	  );
105	}
