1	"use server";
2	
3	import { randomBytes } from "node:crypto";
4	import { revalidatePath } from "next/cache";
5	import { db } from "./db";
6	import { requireUser, assertNotImpersonating } from "./auth";
7	
8	/**
9	 * BUNDLED HOSTING EMAIL
10	 *
11	 * Hosting plans advertise "1 / 10 / 25 mailboxes included", but nothing turned
12	 * that promise into something a customer could use. This module does the ONE
13	 * thing needed to bridge the gap: it mints a COMPLIMENTARY EmailSubscription for
14	 * a hosting account's primary domain, on the matching bundled EmailPlan, then
15	 * hands the customer straight to the existing, audited /dashboard/email UI to add
16	 * mailboxes and verify their domain.
17	 *
18	 * We deliberately write NO new provisioning / Mailcow / SSH code here. The real
19	 * mailbox creation happens through the already-audited addMailbox() path when the
20	 * customer adds a mailbox in /dashboard/email — which enforces the plan quota, the
21	 * external-domain DNS-verification gate, and Mailcow's per-address uniqueness.
22	 *
23	 * SECURITY — the 2026-07-25 cross-tenant email-takeover fix is preserved exactly:
24	 *   1. GLOBAL domain dedup: one EmailSubscription per domain across ALL users. We
25	 *      reuse the identical query subscribeEmail/orderEmailHosting uses. If another
26	 *      tenant already holds the domain we return the SAME "contact support" error
27	 *      and mint nothing — bundled email can never be created for a domain another
28	 *      tenant owns.
29	 *   2. The complimentary subscription is created external:true, verified:false —
30	 *      so even holding the subscription row grants no power over the domain's mail
31	 *      until the customer proves DNS control. addMailbox()/retryMailboxProvision()
32	 *      both refuse to touch Mailcow until then.
33	 */
34	
35	export type HostingEmailResult = { ok?: boolean; error?: string; subscriptionId?: string };
36	
37	/**
38	 * Find the bundled (free, hidden) EmailPlan whose included-mailbox count matches
39	 * the hosting plan's `mailboxes`. Bundled plans are seeded priceCents:0 +
40	 * active:false (see prisma/seed-hosting-email-plans.ts); we match on all three so
41	 * a paid tier that happens to share a mailbox count is never picked up.
42	 */
43	async function findBundledPlan(mailboxes: number) {
44	  return db.emailPlan.findFirst({
45	    where: { mailboxes, priceCents: 0, active: false },
46	    orderBy: { sortOrder: "asc" },
47	  });
48	}
49	
50	/**
51	 * Status for the hosting Email tab: how many mailboxes the plan includes, and
52	 * whether the account's bundled email subscription already exists (so the UI can
53	 * either show "Set up my email" or link into /dashboard/email). Owner or admin.
54	 */
55	export async function getHostingEmailStatus(accountId: string): Promise<{
56	  error?: string;
57	  planName?: string;
58	  primaryDomain?: string;
59	  includedMailboxes?: number;
60	  hasSubscription?: boolean;
61	  subscriptionId?: string;
62	  verified?: boolean;
63	}> {
64	  const user = await requireUser();
65	
66	  const account = await db.hostingAccount.findUnique({
67	    where: { id: accountId },
68	    include: { plan: { select: { name: true, mailboxes: true } } },
69	  });
70	  if (!account) return { error: "Not found." };
71	  if (account.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
72	
73	  // Existing subscription for this domain owned by the ACCOUNT OWNER (bundled or
74	  // paid — either way the owner already controls this domain's mail).
75	  const sub = await db.emailSubscription.findFirst({
76	    where: { domainName: account.primaryDomain, userId: account.userId, status: { not: "CANCELLED" } },
77	    select: { id: true, verified: true },
78	  });
79	
80	  return {
81	    planName: account.plan.name,
82	    primaryDomain: account.primaryDomain,
83	    includedMailboxes: account.plan.mailboxes,
84	    hasSubscription: !!sub,
85	    subscriptionId: sub?.id,
86	    verified: sub?.verified ?? false,
87	  };
88	}
89	
90	/**
91	 * Turn on the bundled email that ships with a hosting account: create a
92	 * complimentary EmailSubscription for the account's primary domain on the
93	 * matching bundled EmailPlan. Owner or admin; blocked while impersonating (a
94	 * complimentary grant is still a mutation made in the customer's name).
95	 *
96	 * Idempotent: if the owner already has a subscription for this domain, no-op.
97	 * No wallet charge is ever taken. No mailboxes are provisioned here — the
98	 * customer adds them via the existing /dashboard/email flow.
99	 */
100	export async function setupHostingEmail(accountId: string): Promise<HostingEmailResult> {
101	  const user = await requireUser();
102	  // A complimentary grant is a mutation attributed to the customer — support must
103	  // not perform it while impersonating, consistent with every other write path.
104	  await assertNotImpersonating();
105	
106	  const account = await db.hostingAccount.findUnique({
107	    where: { id: accountId },
108	    include: { plan: { select: { name: true, mailboxes: true } } },
109	  });
110	  if (!account) return { error: "Not found." };
111	  if (account.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
112	
113	  const domain = account.primaryDomain;
114	
115	  // GLOBAL domain dedup — the exact guard subscribeEmail/orderEmailHosting use.
116	  // One subscription per domain across ALL users (2026-07-25 cross-tenant takeover
117	  // fix). If another tenant holds it, mint NOTHING and return the same support
118	  // message; if the owner already holds it (bundled or paid), this is an
119	  // idempotent no-op.
120	  const dupe = await db.emailSubscription.findFirst({
121	    where: { domainName: domain, status: { not: "CANCELLED" } },
122	  });
123	  if (dupe) {
124	    if (dupe.userId === account.userId) {
125	      // Already set up for the account owner — idempotent success.
126	      return { ok: true, subscriptionId: dupe.id };
127	    }
128	    return {
129	      error:
130	        "That domain is already set up for email on Nxeon. If it belongs to you, contact support and we'll verify ownership and move it across.",
131	    };
132	  }
133	
134	  const plan = await findBundledPlan(account.plan.mailboxes);
135	  if (!plan) {
136	    return {
137	      error:
138	        "Bundled email isn't configured for this plan yet. Please contact support — no charge, we'll switch it on.",
139	    };
140	  }
141	
142	  // Complimentary subscription. EXTERNAL + UNVERIFIED on purpose: holding the row
143	  // grants no power over the domain's mail until the customer proves DNS control
144	  // in /dashboard/email, which is where addMailbox() enforces the gate. autoRenew
145	  // is tied to the hosting account (it renews as long as the hosting lives);
146	  // expiry tracks the account so it doesn't outlive it.
147	  const sub = await db.emailSubscription.create({
148	    data: {
149	      userId: account.userId,
150	      domainName: domain,
151	      emailPlanId: plan.id,
152	      status: "ACTIVE",
153	      autoRenew: true,
154	      expiresAt: account.expiresAt,
155	      external: true,
156	      verified: false,
157	      verifiedAt: null,
158	      verifyToken: randomBytes(24).toString("hex"),
159	    },
160	  });
161	
162	  await db.auditLog
163	    .create({
164	      data: {
165	        userId: account.userId,
166	        action: "hostingemail.setup",
167	        detail: `${domain} · bundled ${plan.name} (${plan.mailboxes} mailbox${plan.mailboxes === 1 ? "" : "es"}) via hosting ${account.plan.name}`,
168	      },
169	    })
170	    .catch(() => {});
171	
172	  revalidatePath(`/dashboard/hosting/${accountId}`);
173	  revalidatePath("/dashboard/email");
174	  return { ok: true, subscriptionId: sub.id };
175	}
