45	/**
46	 * Mail-platform DNS constants. Customers with a domain registered ELSEWHERE
47	 * publish these at their registrar so mail flows through the Nxeon mail server;
48	 * customers whose domain is inside Nxeon have this managed for them.
49	 */
50	const MAIL_HOST = "mail.nxeon.cloud";
51	const MAIL_MX_PRIORITY = 10;
52	// The mechanism that authorises our sending host; kept separate from the full
53	// record so the deliverability check can look for it inside whatever SPF the
54	// customer already publishes rather than demanding a byte-exact match.
55	const SPF_INCLUDE = "nxeon.cloud";
56	const SPF_VALUE = `v=spf1 include:${SPF_INCLUDE} ~all`;
57	const DMARC_VALUE = "v=DMARC1; p=none; rua=mailto:dmarc@nxeon.cloud";
58	const DKIM_SELECTOR = "dkim";
