60	// A syntactically valid registrable domain (labels, no scheme, no trailing dot).
61	const domainRe =
62	  /^(?=.{1,253}$)(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}$/;
63	
64	export type DnsRecord = {
65	  type: "TXT" | "MX";
66	  label: string; // human label for the row
67	  host: string; // record host / name
68	  value: string;
69	  priority?: number;
70	  note?: string;
71	};
