160	): Promise<Result> {
161	  const admin = await requireArea("billing");
162	
163	  const parsed = planSchema.safeParse({
164	    id: formData.get("id") || undefined,
165	    name: formData.get("name"),
166	    mailboxes: formData.get("mailboxes"),
167	    storageGB: formData.get("storageGB"),
168	    priceCents: formData.get("priceCents"),
169	    termMonths: formData.get("termMonths"),
