172	  if (!parsed.success) {
173	    return { error: parsed.error.issues[0]?.message ?? "Check the tier values." };
174	  }
175	  const d = parsed.data;
176	  const active = formData.get("active") === "on";
177	
178	  const data = {
179	    name: d.name.trim(),
180	    mailboxes: d.mailboxes,
181	    storageGB: d.storageGB,
182	    priceCents: d.priceCents,
183	    termMonths: d.termMonths,
184	    active,
185	    sortOrder: d.sortOrder,
186	  };
187	
188	  if (d.id) {
189	    const existing = await db.emailPlan.findUnique({ where: { id: d.id } });
190	    if (!existing) return { error: "Tier not found." };
191	    await db.emailPlan.update({ where: { id: d.id }, data });
192	  } else {
193	    await db.emailPlan.create({ data });
