219	/** Delete a tier. Refused while subscriptions reference it. */
220	export async function adminDeleteEmailPlan(id: string): Promise<Result> {
221	  const admin = await requireArea("billing");
222	  const plan = await db.emailPlan.findUnique({
223	    where: { id },
224	    include: { _count: { select: { subscriptions: true } } },
225	  });
226	  if (!plan) return { error: "Tier not found." };
227	  if (plan._count.subscriptions > 0) {
228	    return {
229	      error: `Can't delete — ${plan._count.subscriptions} subscription(s) use this tier. Disable it instead.`,
230	    };
231	  }
232	  await db.emailPlan.delete({ where: { id } });
233	  await db.auditLog.create({
234	    data: { userId: admin.id, action: "emailplan.delete", detail: plan.name },
235	  });
236	  revalidatePath("/admin/email-plans");
237	  return { ok: true };
238	}
