240	// ---------- Customer ordering ----------
241	
242	/**
243	 * Subscribe one of the caller's registered domains to an email plan. Validates
244	 * domain ownership + plan availability, then atomically debits the wallet and
245	 * creates the EmailSubscription with an expiry set from the plan term.
246	 *
247	 * The subscription is created ACTIVE (billing-wise), but no mailboxes are
248	 * provisioned with a mail provider yet — that integration is pending, and the
249	 * UI surfaces every mailbox as "provisioning" until it lands.
250	 */
251	export async function orderEmailHosting(
252	  domainName: string,
253	  emailPlanId: string,
254	  termMonthsRaw?: number,
255	): Promise<Result> {
256	  const user = await requireUser();
257	  // Spend path: block while an admin is impersonating, so support cannot buy a
258	  // subscription with a customer's wallet while acting as them.
259	  //
260	  // This was the ONE purchase path in the product without this guard — every
261	  // other spend (order, resize, disk expand, volume, domain register/renew/
262	  // transfer, game plan upgrade, top-up) calls it. Impersonation is meant for
263	  // looking, never for spending: `realUser()` is the admin, `currentUser()` is
264	  // the customer, and a debit taken here would come out of the customer's
265	  // balance with the customer's name on the ledger row.
266	  await assertNotImpersonating();
267	  // Purchase gate: an unverified address means we cannot reach the person we
268	  // are about to charge. See lib/email-verification.ts.
269	  const unverified = await emailVerificationError(user);
270	  if (unverified) return { error: unverified };
271	
272	  const name = String(domainName ?? "")
273	    .trim()
274	    .toLowerCase()
275	    .replace(/\.$/, "");
276	  if (!name) return { error: "Enter a domain." };
277	  if (!domainRe.test(name)) return { error: "Enter a valid domain (e.g. example.com)." };
278	
279	  // Is the domain registered inside Nxeon? If so we control its DNS and can
280	  // treat mail as pre-verifiable; otherwise it's an EXTERNAL domain that must be
281	  // verified via DNS before mail flows.
282	  const inAccount = await db.domain.findFirst({ where: { name, userId: user.id } });
283	  const external = !inAccount;
284	
285	  const plan = await db.emailPlan.findUnique({ where: { id: emailPlanId } });
286	  if (!plan || !plan.active) return { error: "That email plan isn't available." };
287	
288	  // One subscription per domain — ACROSS ALL ACCOUNTS, not just this one.
289	  //
290	  // SECURITY (fixed 2026-07-25): this lookup was scoped to `userId: user.id`,
291	  // which let anyone buy a subscription for a domain another customer already
292	  // held. That was a cross-tenant email takeover: `addMailbox` only checks that
293	  // the SUBSCRIPTION belongs to the caller, and Mailcow keys mailboxes by
294	  // ADDRESS — so an attacker could create admin@victim.com under their own
295	  // subscription, call resetMailboxPassword() (which passes its ownership check
296	  // because the row is theirs), and have the password of the victim's real, live
297	  // mailbox handed back to them. Cost of the attack: the cheapest email plan.
298	  const dupe = await db.emailSubscription.findFirst({
299	    where: { domainName: name, status: { not: "CANCELLED" } },
300	  });
301	  if (dupe) {
302	    return {
303	      error:
304	        dupe.userId === user.id
305	          ? "This domain already has an email subscription."
306	          : "That domain is already set up for email on Nxeon. If it belongs to you, contact support and we'll verify ownership and move it across.",
307	    };
308	  }
309	
310	  // Seasonal promo = HONEST intro discount on the FIRST term only. The renewal
311	  // path (worker/product-renewals.ts) bills plan.priceCents unchanged, so the
312	  // strikethrough shown on the pricing page is the real renewal price and this
313	  // discounted value is the real first-term price — displayed === charged.
314	  // Managed first-month-free. `promoCharge` mirrors the pre-existing behaviour
315	  // (the first term is free); `fullCharge` is the plan price. The credit is granted
316	  // ONLY if the atomic claim inside the charge tx succeeds — otherwise (already
317	  // redeemed by this account/IP, or the promo is off) the subscription is created
318	  // at FULL price. The eligibility pre-check only picks the balance gate so a
319	  // first-time, $0-balance customer can still subscribe free.
320	  // First-month-free is scoped to Shared Web Hosting only — Business Email always
321	  // bills full. firstMonthFreeAppliesTo("EMAIL") is false, so promoEnabled is false.
322	  const promoEnabled = firstMonthFreeAppliesTo("EMAIL") && (await firstMonthFreeEnabled());
323	  const campaign = promoCampaignFromCookie(await cookies());
324	  const ipHash = hashIp(clientIp(await headers()), process.env.AUTH_SECRET ?? "nxeon") || null;
325	  // Billing term (Monthly / Annual). The annual rate is resolved ONCE, frozen onto
326	  // the subscription, charged up front and read back at renewal — displayed ===
327	  // charged === renewed. `emailMonthlyBaseCents` is the plan's monthly base (every
328	  // seeded plan is monthly, so it is just `priceCents`).
329	  const term = normalizeProductTerm(termMonthsRaw);
330	  const annualPct = await annualDiscountPct();
331	  const fullCharge = termPriceCents(emailMonthlyBaseCents(plan), term, annualPct);
332	  // Business Email is NOT a first-month-free product (firstMonthFreeAppliesTo("EMAIL")
333	  // is false), so this stays the full term charge — kept for parity with the other flows.
334	  const promoCharge = 0;
335	  const eligible = promoEnabled && (await firstMonthFreeEligible(user.id, ipHash));
336	  const anticipated = eligible ? promoCharge : fullCharge;
337	  if (user.balanceCents < anticipated) {
338	    return { error: "Insufficient balance. Top up your wallet first." };
339	  }
340	
341	  try {
342	    await db.$transaction(async (tx) => {
343	      // Atomic claim inside the charge tx (mirrors lib/order.ts claimOrderCoupon).
344	      let debitCents = fullCharge;
345	      let promoClaimId: string | null = null;
346	      if (promoEnabled) {
347	        const claim = await claimFirstMonthFree(tx, {
348	          userId: user.id,
349	          ipHash,
350	          serviceType: "EMAIL",
351	          campaign,
352	          chargedCents: promoCharge,
353	        });
354	        if (claim.claimed) {
355	          debitCents = promoCharge;
356	          promoClaimId = claim.id;
357	        }
358	      }
359	      const note = debitCents < fullCharge ? " — First month free" : "";
360	      const effMonthly = term > 1 ? Math.round(fullCharge / term) : 0;
361	      const termLabel = term > 1 ? `${vpsTerm(term).label} ($${(effMonthly / 100).toFixed(2)}/mo)` : vpsTerm(term).label;
362	      await debitWallet(tx, user.id, debitCents);
363	      await tx.walletTransaction.create({
364	        data: {
365	          userId: user.id,
366	          amountCents: -debitCents,
367	          description: `Business Email: ${plan.name} for ${name} — ${termLabel}${note}`,
368	        },
369	      });
370	      const sub = await tx.emailSubscription.create({
371	        // Cast: the symlinked prod Prisma client's types predate `termMonths` /
372	        // `annualDiscountPct` on EmailSubscription until regenerated at deploy.
373	        data: {
374	          userId: user.id,
375	          domainName: name,
376	          emailPlanId: plan.id,
377	          status: "ACTIVE",
378	          autoRenew: true,
379	          // The term the customer chose, and the annual rate frozen at sale, so the
380	          // renewal sweep bills the SAME price it was ordered at.
381	          termMonths: term,
382	          annualDiscountPct: annualPct,
383	          expiresAt: addMonths(new Date(), term),
384	          // In-account domains: we control DNS, so treat as verified now. External
385	          // domains: not verified until the customer publishes DNS + we confirm it.
386	          external,
387	          verified: !external,
388	          verifiedAt: external ? null : new Date(),
389	          verifyToken: external ? randomBytes(24).toString("hex") : null,
390	        } as Prisma.EmailSubscriptionUncheckedCreateInput,
391	      });
392	      if (promoClaimId) await setPromoOrderRef(tx, promoClaimId, sub.id, debitCents);
393	    });
394	  } catch (e) {
395	    if (e instanceof InsufficientBalanceError) {
396	      return { error: "Insufficient balance. Top up your wallet first." };
397	    }
398	    throw e;
399	  }
400	
401	  await db.auditLog.create({
402	    data: {
403	      userId: user.id,
404	      action: "emailhosting.order",
405	      detail: `${name} plan=${plan.name}${external ? " (external — DNS verification required)" : ""}`,
406	    },
407	  });
408	  revalidatePath("/dashboard/email");
409	  return { ok: true };
410	}
