432	  const user = await requireUser();
433	
434	  const sub = await db.emailSubscription.findUnique({ where: { id: subscriptionId } });
435	  if (!sub) return { error: "Subscription not found." };
436	  if (sub.userId !== user.id) return { error: "Not your subscription." };
437	
438	  const domain = sub.domainName;
439	
440	  // Resolve the DKIM TXT: prefer the cached value, else fetch + cache from Mailcow.
441	  let dkimTxt = sub.dkimRecord ?? null;
442	  if (!dkimTxt && mailcowConfigured()) {
443	    try {
444	      // Ensure the mail domain exists so Mailcow has generated a DKIM key.
