453	      }
454	    } catch (e) {
455	      console.warn(`[mailcow] get dkim ${domain} failed:`, e);
456	    }
457	  }
458	
459	  const records: DnsRecord[] = [
460	    {
461	      type: "TXT",
462	      label: "Ownership verification",
463	      host: `_nxeon-verify.${domain}`,
464	      value: `nxeon-verify=${sub.verifyToken ?? ""}`,
465	      note: "Proves you control this domain. Required before mail is enabled.",
466	    },
467	    {
468	      type: "MX",
469	      label: "Mail routing (MX)",
470	      host: domain,
471	      value: MAIL_HOST,
472	      priority: MAIL_MX_PRIORITY,
473	    },
474	    {
475	      type: "TXT",
476	      label: "SPF",
477	      host: domain,
478	      value: SPF_VALUE,
479	      note: "Authorizes the Nxeon mail server to send for your domain.",
480	    },
481	    {
482	      type: "TXT",
483	      label: "DKIM",
484	      host: `${DKIM_SELECTOR}._domainkey.${domain}`,
485	      value: dkimTxt ?? "",
486	      note: dkimTxt
487	        ? undefined
488	        : "DKIM key is being generated on the mail server — refresh this page shortly to see the value.",
489	    },
490	    {
491	      type: "TXT",
492	      label: "DMARC",
493	      host: `_dmarc.${domain}`,
494	      value: DMARC_VALUE,
495	      note: "Reporting policy for messages that fail SPF/DKIM.",
496	    },
