652	/**
653	 * Add a mailbox to a subscription the caller owns. Enforces the plan's mailbox
654	 * quota and address uniqueness within the subscription, records the intended
655	 * mailbox (status PROVISIONING), then attempts to provision it on Mailcow. A
656	 * Mailcow failure leaves the row as FAILED (retryable) but never fails the call.
657	 */
658	export async function addMailbox(subscriptionId: string, localPart: string): Promise<Result> {
659	  const user = await requireUser();
660	
661	  const sub = await db.emailSubscription.findUnique({
662	    where: { id: subscriptionId },
663	    include: { emailPlan: true, mailboxes: true },
664	  });
665	  if (!sub) return { error: "Subscription not found." };
666	  if (sub.userId !== user.id) return { error: "Not your subscription." };
667	  if (sub.status === "CANCELLED") return { error: "This subscription is cancelled." };
668	  // SECURITY (added 2026-07-25): defence in depth against the cross-tenant
669	  // takeover fixed in subscribeEmail(). Owning the subscription ROW is not proof
670	  // of owning the DOMAIN — and because Mailcow keys mailboxes by address, any
671	  // mailbox minted here acts on that domain's real mail. An external domain must
672	  // prove control via DNS before it can mint a single address, so even if a
673	  // duplicate subscription is ever created again this cannot be weaponised.
674	  if (sub.external && !sub.verified) {
675	    return {
676	      error: "Verify this domain first — add the DNS record shown on this page, then click Verify.",
677	    };
678	  }
679	
680	  const local = String(localPart ?? "").trim().toLowerCase();
681	  if (!localPartRe.test(local) || local.length > 64) {
682	    return { error: "Enter a valid mailbox name (letters, numbers, . _ - )." };
683	  }
684	
685	  const address = `${local}@${sub.domainName}`;
686	
687	  if (sub.mailboxes.length >= sub.emailPlan.mailboxes) {
688	    return {
689	      error: `Plan limit reached (${sub.emailPlan.mailboxes} mailbox${sub.emailPlan.mailboxes === 1 ? "" : "es"}). Upgrade to add more.`,
690	    };
691	  }
692	  if (sub.mailboxes.some((m) => m.address.toLowerCase() === address)) {
693	    return { error: "That address already exists." };
694	  }
695	
696	  // Per-mailbox quota (MB) comes from the plan tier's per-mailbox storage (GB).
697	  const quotaMB = sub.emailPlan.storageGB * 1024;
698	
699	  const mailbox = await db.mailbox.create({
700	    data: { subscriptionId: sub.id, address, quotaMB, status: "PROVISIONING" },
701	  });
702	
703	  await db.auditLog.create({
704	    data: { userId: user.id, action: "mailbox.add", detail: address },
705	  });
706	
707	  // Additive, failure-tolerant provisioning — never throws out of the flow.
708	  await provisionMailboxOnMailcow({
709	    id: mailbox.id,
710	    address: mailbox.address,
711	    quotaMB,
712	    subscription: { domainName: sub.domainName },
713	  });
714	
715	  revalidatePath("/dashboard/email");
716	  return { ok: true };
717	}
