829	 * Suspend or resume a mailbox the caller owns, mirroring the state onto Mailcow
830	 * (deactivate/activate). Owner-only, failure-tolerant on the Mailcow call.
831	 */
832	export async function setMailboxSuspended(mailboxId: string, suspended: boolean): Promise<Result> {
833	  const user = await requireUser();
834	
835	  const mailbox = await db.mailbox.findUnique({
836	    where: { id: mailboxId },
837	    include: { subscription: true },
838	  });
839	  if (!mailbox) return { error: "Mailbox not found." };
840	  if (mailbox.subscription.userId !== user.id) return { error: "Not your mailbox." };
841	
842	  // A REFUSAL means the flip did not happen on the mail server, so writing our
843	  // status to SUSPENDED/ACTIVE would be a lie the customer acts on — a "suspended"
844	  // mailbox that keeps sending and receiving, or vice versa. Only an UNREACHABLE
845	  // server is tolerated (the state will reconcile), and even then the customer is
846	  // told the mail server did not confirm.
847	  let mailcowUnreachable = false;
848	  if (mailcowConfigured()) {
849	    try {
850	      await mcSetMailboxActive(mailbox.address, !suspended);
851	    } catch (e) {
852	      if (isMailcowUnreachable(e)) {
853	        mailcowUnreachable = true;
854	        console.warn(`[mailcow] set active ${mailbox.address}: unreachable, updating local status anyway:`, e);
855	      } else {
856	        console.error(`[mailcow] set active ${mailbox.address} REFUSED:`, e);
857	        return {
858	          error: `The mail server wouldn't ${suspended ? "suspend" : "resume"} this mailbox, so nothing was changed. Please try again in a moment.`,
859	        };
860	      }
861	    }
862	  }
863	
864	  await db.mailbox.update({
865	    where: { id: mailbox.id },
866	    data: { status: suspended ? "SUSPENDED" : "ACTIVE" },
867	  });
868	
869	  await db.auditLog.create({
870	    data: {
871	      userId: user.id,
872	      action: suspended ? "mailbox.suspend" : "mailbox.resume",
873	      detail: mailbox.address,
874	    },
875	  });
876	  revalidatePath("/dashboard/email");
877	  return mailcowUnreachable
878	    ? {
879	        ok: true,
880	        warning: `Updated in your account, but the mail server was unreachable so it may not be ${suspended ? "suspended" : "active"} yet — it will reconcile when mail service is back.`,
881	      }
882	    : { ok: true };
883	}
