975	 * mail DNS records for them. The token is verified against Cloudflare before it
976	 * is saved, so we never persist a dud. requireUser + rate-limited; the token is
977	 * never logged or returned. Scope guidance (Zone → DNS → Edit) lives in the UI.
978	 */
979	export async function saveCloudflareToken(token: string): Promise<Result> {
980	  const user = await requireUser();
981	
982	  const t = String(token ?? "").trim();
983	  if (!t) return { error: "Paste your Cloudflare API token." };
984	  if (t.length < 20 || t.length > 200) {
985	    return { error: "That doesn't look like a Cloudflare API token." };
986	  }
987	
988	  const rl = checkRateLimit(`cf-token:${user.id}`, { max: 6, windowMs: 60_000 });
989	  if (!rl.ok) return { error: `Too many attempts. Try again in ${rl.retryAfterSec}s.` };
990	
991	  let valid = false;
992	  try {
993	    valid = await cfVerifyToken(t);
994	  } catch (e) {
995	    console.warn("[cloudflare] token verify failed:", e);
996	    return { error: "Couldn't reach Cloudflare to verify the token. Try again shortly." };
997	  }
998	  if (!valid) {
999	    return {
1000	      error: "Cloudflare rejected that token. Check it's active and scoped to Zone → DNS → Edit.",
1001	    };
1002	  }
1003	
1004	  await db.user.update({
1005	    where: { id: user.id },
1006	    data: { cloudflareTokenEnc: encryptSecret(t) },
1007	  });
1008	  await db.auditLog.create({
1009	    data: { userId: user.id, action: "cloudflare.connect", detail: "API token saved" },
1010	  });
1011	  revalidatePath("/dashboard/email");
1012	  return { ok: true };
1013	}
