1015	/**
1016	 * Auto-create the mail DNS records for an EXTERNAL email subscription in the
1017	 * customer's Cloudflare zone, using their stored token. Ownership-checked and
1018	 * rate-limited. Reuses getEmailDnsRecords as the single source of truth for the
1019	 * record set (ownership verify TXT, MX, SPF, DKIM, DMARC), upserts each into the
1020	 * zone, then leaves the existing verifyEmailDomain flow to confirm. Fails
1021	 * gracefully with clear messages for invalid token / zone-not-found.
1022	 */
1023	export async function autoCreateEmailDns(
1024	  subscriptionId: string,
1025	): Promise<{ error?: string; ok?: boolean; created?: string[] }> {
1026	  const user = await requireUser();
1027	
1028	  const sub = await db.emailSubscription.findUnique({ where: { id: subscriptionId } });
1029	  if (!sub) return { error: "Subscription not found." };
1030	  if (sub.userId !== user.id) return { error: "Not your subscription." };
1031	  if (!sub.external) {
1032	    return { error: "This domain is managed by Nxeon — no external DNS setup is needed." };
1033	  }
1034	
1035	  const rl = checkRateLimit(`cf-autodns:${user.id}:${sub.id}`, { max: 4, windowMs: 60_000 });
1036	  if (!rl.ok) return { error: `Too many attempts. Try again in ${rl.retryAfterSec}s.` };
1037	
1038	  // Works for both connection shapes: OAuth credentials (refreshed here when
1039	  // stale) and a legacy pasted API token. Never handles the plaintext itself.
1040	  const resolved = await resolveCloudflareToken(user);
1041	  const token = resolved.token;
1042	  if (!token) return { error: resolved.error ?? "Connect Cloudflare first." };
1043	
1044	  // Same record set the customer would otherwise publish by hand.
1045	  const dns = await getEmailDnsRecords(subscriptionId);
1046	  if (dns.error) return { error: dns.error };
1047	  const records = (dns.records ?? []).filter((r) => r.type === "MX" || r.value.trim());
1048	  if (records.length === 0) {
1049	    return { error: "No DNS records to create yet — try again in a moment." };
1050	  }
1051	
1052	  // SANDBOX: never contact Cloudflare — report what we would have published so
1053	  // staging can walk the whole "connect → records added" flow.
1054	  if (SANDBOX) {
1055	    return {
1056	      ok: true,
1057	      created: records.map((r) => `${r.label} (${r.type}, created)`),
1058	    };
1059	  }
1060	
1061	  let zoneId: string | null;
1062	  try {
1063	    zoneId = await cfFindZoneId(token, sub.domainName);
1064	  } catch (e) {
1065	    if (e instanceof CloudflareError) {
1066	      return { error: `Cloudflare error: ${e.message}` };
1067	    }
1068	    throw e;
1069	  }
1070	  if (!zoneId) {
1071	    return {
1072	      error: `No Cloudflare zone found for ${sub.domainName}. Add the domain to Cloudflare first, or check the token is scoped to this zone.`,
1073	    };
1074	  }
1075	
1076	  let created: string[];
1077	  try {
1078	    const results = await cfUpsertRecords(
1079	      token,
1080	      zoneId,
1081	      records.map((r) => ({
1082	        type: r.type,
1083	        name: r.host,
1084	        content: r.value,
1085	        priority: r.priority,
1086	      })),
1087	    );
1088	    created = results.map((res) => {
1089	      const label = records.find((r) => r.host === res.name && r.type === res.type)?.label ?? res.name;
1090	      return `${label} (${res.type}, ${res.action})`;
1091	    });
1092	  } catch (e) {
1093	    if (e instanceof CloudflareError) {
1094	      return {
1095	        error: `Couldn't create records in Cloudflare: ${e.message}. Check the token has Zone → DNS → Edit permission.`,
1096	      };
1097	    }
1098	    throw e;
1099	  }
1100	
1101	  await db.auditLog.create({
1102	    data: {
1103	      userId: user.id,
1104	      action: "cloudflare.autodns",
1105	      detail: `${sub.domainName} — ${created.length} record(s)`,
1106	    },
1107	  });
1108	  revalidatePath("/dashboard/email");
1109	  return { ok: true, created };
1110	}
