/**
 * Mail-platform DNS constants + record builder — the SINGLE source of truth for
 * the records a domain must publish to send/receive through the Nxeon mail server.
 *
 * This is a plain module (NOT "use server") on purpose: a "use server" file may
 * only export async functions, so the constants and the pure record-builder can't
 * live in lib/actions-email-hosting.ts and still be shared. Both that file (paid
 * Business Email) and lib/hosting-email.ts (bundled hosting email) import from here
 * so the MX host / SPF / DKIM selector never drift between the two flows.
 */

import { HOSTING_SUBDOMAIN_BASE, isFreeSubdomain } from "../hosting";
import { SANDBOX } from "../sandbox";
import { cfFindZoneId, cfUpsertRecords, CloudflareError } from "../cloudflare-dns";
import {
  mailcowConfigured,
  mcCreateDomain,
  mcDomainExists,
  mcGetDkim,
} from "../mailcow";

/** Customers with a domain registered elsewhere publish these at their registrar
 *  so mail flows through the Nxeon mail server; domains whose zone WE control have
 *  the same records managed for them. */
export const MAIL_HOST = "mail.nxeon.cloud";
export const MAIL_MX_PRIORITY = 10;
// The mechanism that authorises our sending host; kept separate from the full
// record so the deliverability check can look for it inside whatever SPF the
// customer already publishes rather than demanding a byte-exact match.
export const SPF_INCLUDE = "nxeon.cloud";
export const SPF_VALUE = `v=spf1 include:${SPF_INCLUDE} ~all`;
export const DMARC_VALUE = "v=DMARC1; p=none; rua=mailto:dmarc@nxeon.cloud";
export const DKIM_SELECTOR = "dkim";

export type DnsRecord = {
  type: "TXT" | "MX";
  label: string; // human label for the row
  host: string; // record host / name
  value: string;
  priority?: number;
  note?: string;
};

/**
 * The mail DNS record set for a domain. `verifyToken` adds the ownership TXT
 * (only meaningful for EXTERNAL domains the customer must prove control of);
 * `dkimTxt` fills in the DKIM value once the mail server has generated the key.
 */
export function mailDnsRecordsFor(
  domain: string,
  opts: { verifyToken?: string | null; dkimTxt?: string | null } = {},
): DnsRecord[] {
  const records: DnsRecord[] = [];
  if (opts.verifyToken) {
    records.push({
      type: "TXT",
      label: "Ownership verification",
      host: `_nxeon-verify.${domain}`,
      value: `nxeon-verify=${opts.verifyToken}`,
      note: "Proves you control this domain. Required before mail is enabled.",
    });
  }
  records.push(
    { type: "MX", label: "Mail routing (MX)", host: domain, value: MAIL_HOST, priority: MAIL_MX_PRIORITY },
    {
      type: "TXT",
      label: "SPF",
      host: domain,
      value: SPF_VALUE,
      note: "Authorizes the Nxeon mail server to send for your domain.",
    },
    {
      type: "TXT",
      label: "DKIM",
      host: `${DKIM_SELECTOR}._domainkey.${domain}`,
      value: opts.dkimTxt ?? "",
      note: opts.dkimTxt
        ? undefined
        : "DKIM key is being generated on the mail server — refresh shortly to see the value.",
    },
    {
      type: "TXT",
      label: "DMARC",
      host: `_dmarc.${domain}`,
      value: DMARC_VALUE,
      note: "Reporting policy for messages that fail SPF/DKIM.",
    },
  );
  return records;
}

export type FreeSubdomainDnsResult = {
  /** True once the mail records are actually published in our zone (or simulated in sandbox). */
  ok: boolean;
  /** Human labels of the records published — for the audit line / UI. */
  published: string[];
  /** Set when we could not publish yet (missing platform token / mail server) — NOT a hard error. */
  pending: boolean;
  /** One line explaining the outcome. */
  note: string;
};

/**
 * Auto-publish the mail records (MX / SPF / DKIM / DMARC) for one of OUR free
 * subdomains (`*.<HOSTING_SUBDOMAIN_BASE>`) into the platform zone we control,
 * using the platform Cloudflare token (CLOUDFLARE_DNS_API_TOKEN — the same
 * credential the wildcard-cert DNS-01 uses). Because we own the zone, the customer
 * never touches DNS: bundled email on a free subdomain "just works".
 *
 * Best-effort and never throws — callers treat a `pending` result as "records will
 * follow" and let the deliverability self-check surface the real state, so we never
 * claim success we didn't achieve.
 *
 *  - SANDBOX: the whole node/DNS layer is mocked, so we SIMULATE a publish (the
 *    DB/UI flow stays fully testable in staging) without touching Cloudflare.
 *  - No platform token, or mail server not configured, or the zone can't be found:
 *    return `pending` with a clear note — nothing is faked.
 */
export async function provisionFreeSubdomainMailDns(subdomain: string): Promise<FreeSubdomainDnsResult> {
  const domain = String(subdomain ?? "").trim().toLowerCase().replace(/\.$/, "");
  if (!isFreeSubdomain(domain)) {
    return { ok: false, pending: false, published: [], note: "Not a free Nxeon subdomain." };
  }

  const labels = ["Mail routing (MX)", "SPF", "DKIM", "DMARC"];

  if (SANDBOX) {
    return {
      ok: true,
      pending: false,
      published: labels,
      note: "Sandbox — DNS auto-configuration simulated (no external calls).",
    };
  }

  const token = String(process.env.CLOUDFLARE_DNS_API_TOKEN ?? "").trim();
  if (!token) {
    return {
      ok: false,
      pending: true,
      published: [],
      note: "Platform DNS token not configured — records will be published once it is.",
    };
  }

  // DKIM comes from the mail server, which must know the domain first. Best-effort:
  // a missing key just means the DKIM row is published empty and refreshed later.
  let dkimTxt: string | null = null;
  if (mailcowConfigured()) {
    try {
      if (!(await mcDomainExists(domain))) await mcCreateDomain(domain).catch(() => {});
      dkimTxt = await mcGetDkim(domain);
    } catch (e) {
      console.warn(`[hosting-email] mailcow dkim for ${domain} failed:`, e);
    }
  } else {
    return {
      ok: false,
      pending: true,
      published: [],
      note: "Mail server not configured yet — records will be published once it is.",
    };
  }

  try {
    const zoneId = await cfFindZoneId(token, HOSTING_SUBDOMAIN_BASE);
    if (!zoneId) {
      return {
        ok: false,
        pending: true,
        published: [],
        note: `Zone ${HOSTING_SUBDOMAIN_BASE} not found on the platform Cloudflare account.`,
      };
    }
    // No ownership TXT — we own the zone, so there is nothing to prove.
    const records = mailDnsRecordsFor(domain, { dkimTxt }).filter(
      (r) => r.type === "MX" || r.value.trim(),
    );
    await cfUpsertRecords(
      token,
      zoneId,
      records.map((r) => ({ type: r.type, name: r.host, content: r.value, priority: r.priority })),
    );
    return {
      ok: true,
      pending: false,
      published: records.map((r) => r.label),
      note: `Published ${records.length} record(s) in ${HOSTING_SUBDOMAIN_BASE}.`,
    };
  } catch (e) {
    if (e instanceof CloudflareError) {
      console.warn(`[hosting-email] cloudflare publish for ${domain} failed:`, e.message);
      return { ok: false, pending: true, published: [], note: `Cloudflare error: ${e.message}` };
    }
    console.warn(`[hosting-email] free-subdomain DNS publish for ${domain} failed:`, e);
    return { ok: false, pending: true, published: [], note: "Couldn't publish DNS right now — will retry." };
  }
}

