"use server";

import { randomBytes } from "node:crypto";
import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireUser, assertNotImpersonating } from "./auth";
import { isFreeSubdomain } from "./hosting";
import { provisionFreeSubdomainMailDns } from "./mail/platform-dns";

/**
 * BUNDLED HOSTING EMAIL — now PER-DOMAIN, not pinned to the setup subdomain.
 *
 * Hosting plans advertise "1 / 10 / 25 mailboxes included". This module mints the
 * COMPLIMENTARY EmailSubscription that delivers that promise — but the customer now
 * chooses WHICH of their account's domains it attaches to (the primary domain, a
 * subdomain, or a real addon domain they own), instead of it being hard-pinned to
 * the free `*.sites.nxeon.cloud` subdomain the account happened to be set up with.
 *
 * WHY per-domain: the free subdomain sits under a zone WE own, so a customer could
 * never publish the MX/SPF/DKIM a real mailbox needs — mail on it was a
 * deliverability dead-end. Attaching mail to a domain the customer controls (where
 * they add MX/SPF/DKIM at their registrar) is the only setup that actually works;
 * for a free subdomain WE auto-publish the records since we own that zone.
 *
 * The bundled subscription is a normal EmailSubscription, so once it points at a
 * domain the audited /dashboard/email flow (addMailbox, getEmailDnsRecords,
 * verifyEmailDomain, checkEmailDeliverability) manages mailboxes + DNS for THAT
 * domain unchanged. `EmailSubscription.hostingAccountId` is the new link that marks
 * which subscription is the bundled one and ties it to this account.
 *
 * QUOTA / SECURITY invariants preserved exactly:
 *   - ONE bundled subscription per hosting account. Its bundled EmailPlan's mailbox
 *     count == the hosting plan's `mailboxes`, so the existing per-subscription cap
 *     in addMailbox() IS the account's included-mailbox budget — no way to multiply
 *     the entitlement by spreading it over several domains.
 *   - GLOBAL domain dedup (one EmailSubscription per domain across ALL users — the
 *     2026-07-25 cross-tenant email-takeover fix) is enforced on both setup and
 *     re-point, using the identical query subscribeEmail/orderEmailHosting use.
 *   - EXTERNAL (real) domains are created external:true, verified:false — holding
 *     the row grants no power over the domain's mail until the customer proves DNS
 *     control; addMailbox()/retryMailboxProvision() refuse to touch Mailcow first.
 *   - FREE subdomains are created external:false, verified:true (we own the zone,
 *     exactly like an in-account domain in orderEmailHosting) and we best-effort
 *     auto-publish the records — the deliverability self-check surfaces the truth.
 */

export type HostingEmailResult = { ok?: boolean; error?: string; subscriptionId?: string };

type DomainKind = "primary" | "subdomain" | "addon";

export type HostingMailDomainOption = {
  host: string;
  kind: DomainKind;
  /** True when it's one of our free `*.sites.nxeon.cloud` subdomains → we auto-configure DNS. */
  free: boolean;
  /** Some non-cancelled email subscription already exists for this host (anyone's). */
  hasEmail: boolean;
  /** Held by ANOTHER account/tenant — can't be attached here (global domain dedup). */
  takenByOther: boolean;
  /** This host is the account's CURRENT bundled mail domain. */
  isCurrent: boolean;
};

export type HostingMailbox = { id: string; address: string; status: string; createdAt: string };

export type HostingBundledEmail = {
  subscriptionId: string;
  domainName: string;
  kind: DomainKind;
  free: boolean;
  external: boolean;
  verified: boolean;
  status: string;
  mailboxes: HostingMailbox[];
  mailboxCap: number;
};

export type HostingEmailStatus = {
  error?: string;
  planName?: string;
  includedMailboxes?: number;
  primaryDomain?: string;
  /** Every domain on the account the customer may attach mail to. */
  domainOptions?: HostingMailDomainOption[];
  /** The current bundled mail domain + its mailboxes, or null if not set up yet. */
  bundled?: HostingBundledEmail | null;
  /** Convenience flag the UI can gate on. */
  hasSubscription?: boolean;
};

const domainRe =
  /^(?=.{1,253}$)(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}$/;

function normalizeDomain(d: string): string {
  return String(d ?? "").trim().toLowerCase().replace(/\.$/, "");
}

/**
 * Find the bundled (free, hidden) EmailPlan whose included-mailbox count matches
 * the hosting plan's `mailboxes`. Bundled plans are seeded priceCents:0 +
 * active:false (see prisma/seed-hosting-email-plans.ts); we match on all three so
 * a paid tier that happens to share a mailbox count is never picked up.
 */
async function findBundledPlan(mailboxes: number) {
  return db.emailPlan.findFirst({
    where: { mailboxes, priceCents: 0, active: false },
    orderBy: { sortOrder: "asc" },
  });
}

type AccountWithDomains = {
  id: string;
  userId: string;
  primaryDomain: string;
  expiresAt: Date | null;
  plan: { name: string; mailboxes: number };
  subdomains: { fqdn: string }[];
  addonDomains: { domain: string }[];
};

/** Load the account with everything needed to enumerate its mail-domain options. */
async function loadAccount(accountId: string): Promise<AccountWithDomains | null> {
  return db.hostingAccount.findUnique({
    where: { id: accountId },
    select: {
      id: true,
      userId: true,
      primaryDomain: true,
      expiresAt: true,
      plan: { select: { name: true, mailboxes: true } },
      subdomains: { select: { fqdn: true } },
      addonDomains: { select: { domain: true } },
    },
  });
}

/** The ordered list of hosts the account may host mail on, tagged with their kind. */
function accountDomains(a: AccountWithDomains): { host: string; kind: DomainKind }[] {
  const out: { host: string; kind: DomainKind }[] = [
    { host: normalizeDomain(a.primaryDomain), kind: "primary" },
  ];
  for (const s of a.subdomains) out.push({ host: normalizeDomain(s.fqdn), kind: "subdomain" });
  for (const d of a.addonDomains) out.push({ host: normalizeDomain(d.domain), kind: "addon" });
  // De-dupe defensively (a promoted addon can equal the primary for a moment).
  const seen = new Set<string>();
  return out.filter((o) => o.host && !seen.has(o.host) && seen.add(o.host));
}

function kindOf(a: AccountWithDomains, host: string): DomainKind {
  const h = normalizeDomain(host);
  if (h === normalizeDomain(a.primaryDomain)) return "primary";
  if (a.subdomains.some((s) => normalizeDomain(s.fqdn) === h)) return "subdomain";
  return "addon";
}

/**
 * Status for the hosting Email tab: the plan's included mailbox count, every domain
 * on the account the customer can attach mail to, and the current bundled mail
 * domain (with its mailboxes) if one exists. Owner or admin.
 */
export async function getHostingEmailStatus(accountId: string): Promise<HostingEmailStatus> {
  const user = await requireUser();

  const account = await loadAccount(accountId);
  if (!account) return { error: "Not found." };
  if (account.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };

  const domains = accountDomains(account);
  const hosts = domains.map((d) => d.host);

  // Every non-cancelled subscription touching any of the account's domains — used
  // for the global-dedup availability flags AND to locate the bundled subscription.
  const subs = hosts.length
    ? await db.emailSubscription.findMany({
        where: { domainName: { in: hosts }, status: { not: "CANCELLED" } },
        include: { emailPlan: true, mailboxes: true },
      })
    : [];

  // The bundled subscription: preferably the one explicitly linked to this account;
  // otherwise a pre-existing bundled row (bundled plan on the primary domain, no
  // link) which we self-heal by adopting the link now (back-compat migration).
  let bundledSub =
    subs.find((s) => s.hostingAccountId === account.id) ??
    subs.find(
      (s) =>
        s.hostingAccountId == null &&
        s.userId === account.userId &&
        s.domainName === normalizeDomain(account.primaryDomain) &&
        s.emailPlan.priceCents === 0 &&
        s.emailPlan.active === false,
    ) ??
    null;

  if (bundledSub && bundledSub.hostingAccountId == null) {
    await db.emailSubscription
      .update({ where: { id: bundledSub.id }, data: { hostingAccountId: account.id } })
      .catch(() => {});
    bundledSub = { ...bundledSub, hostingAccountId: account.id };
  }

  const bundledHost = bundledSub?.domainName ?? null;

  const domainOptions: HostingMailDomainOption[] = domains.map((d) => {
    const here = subs.filter((s) => s.domainName === d.host);
    const takenByOther = here.some((s) => s.userId !== account.userId);
    return {
      host: d.host,
      kind: d.kind,
      free: isFreeSubdomain(d.host),
      hasEmail: here.length > 0,
      takenByOther,
      isCurrent: d.host === bundledHost,
    };
  });

  const bundled: HostingBundledEmail | null = bundledSub
    ? {
        subscriptionId: bundledSub.id,
        domainName: bundledSub.domainName,
        kind: kindOf(account, bundledSub.domainName),
        free: isFreeSubdomain(bundledSub.domainName),
        external: bundledSub.external,
        verified: bundledSub.verified,
        status: bundledSub.status,
        mailboxCap: bundledSub.emailPlan.mailboxes,
        mailboxes: bundledSub.mailboxes
          .slice()
          .sort((a, b) => a.createdAt.getTime() - b.createdAt.getTime())
          .map((m) => ({
            id: m.id,
            address: m.address,
            status: m.status,
            createdAt: m.createdAt.toISOString(),
          })),
      }
    : null;

  return {
    planName: account.plan.name,
    includedMailboxes: account.plan.mailboxes,
    primaryDomain: normalizeDomain(account.primaryDomain),
    domainOptions,
    bundled,
    hasSubscription: !!bundled,
  };
}

/**
 * Shared guard for the two mutations: load + own the account, validate the chosen
 * domain is one of the account's, and enforce the global one-subscription-per-domain
 * rule. Returns the account + the resolved domain kind, or an error.
 */
async function resolveTargetDomain(
  accountId: string,
  domainNameRaw: string,
  opts: { ignoreSubscriptionId?: string } = {},
): Promise<
  | { error: string }
  | { account: AccountWithDomains; domain: string; kind: DomainKind; free: boolean }
> {
  const user = await requireUser();

  const account = await loadAccount(accountId);
  if (!account) return { error: "Not found." };
  if (account.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
  if (account.plan.mailboxes <= 0) {
    return { error: "This plan doesn't include any mailboxes. Upgrade to add email." };
  }

  const domain = normalizeDomain(domainNameRaw);
  if (!domain) return { error: "Choose a domain for your email." };

  const options = accountDomains(account);
  const match = options.find((o) => o.host === domain);
  if (!match) {
    return { error: "That domain isn't on this hosting account. Add it in the Domains tab first." };
  }
  // Free subdomains legitimately aren't registrable-domain shaped; only validate the
  // shape of real domains.
  const free = isFreeSubdomain(domain);
  if (!free && !domainRe.test(domain)) {
    return { error: "That doesn't look like a valid domain." };
  }

  // GLOBAL domain dedup — one subscription per domain across ALL users.
  const dupe = await db.emailSubscription.findFirst({
    where: { domainName: domain, status: { not: "CANCELLED" } },
  });
  if (dupe && dupe.id !== opts.ignoreSubscriptionId) {
    if (dupe.userId !== account.userId) {
      return {
        error:
          "That domain is already set up for email on Nxeon. If it belongs to you, contact support and we'll verify ownership and move it across.",
      };
    }
    // Owned by this customer already (e.g. a separate paid Business Email order, or
    // the bundled sub itself when it's not the one we're ignoring).
    return { error: "This domain already has email. Manage it from the email dashboard." };
  }

  return { account, domain, kind: match.kind, free };
}

/** Fire-and-forget free-subdomain DNS auto-publish + audit note. Never throws. */
async function autoConfigureFreeSubdomain(userId: string, domain: string): Promise<void> {
  try {
    const res = await provisionFreeSubdomainMailDns(domain);
    await db.auditLog
      .create({
        data: {
          userId,
          action: "hostingemail.autodns",
          detail: `${domain} · ${res.ok ? "published" : "pending"} — ${res.note}`,
        },
      })
      .catch(() => {});
  } catch (e) {
    console.warn(`[hosting-email] free-subdomain auto-config for ${domain} failed:`, e);
  }
}

/**
 * Turn on bundled email for a hosting account, attaching the included mailboxes to
 * the customer-chosen domain. Owner or admin; blocked while impersonating.
 *
 * Idempotent for the SAME domain. Single bundled subscription per account: if one
 * already exists on a different domain, the caller is told to move it instead (see
 * changeHostingEmailDomain) so the mailbox budget can never be spread across
 * several bundled subscriptions.
 */
export async function setupHostingEmail(
  accountId: string,
  domainName: string,
): Promise<HostingEmailResult> {
  const user = await requireUser();
  await assertNotImpersonating();

  const resolved = await resolveTargetDomain(accountId, domainName);
  if ("error" in resolved) return { error: resolved.error };
  const { account, domain, free } = resolved;

  // Single bundled subscription per account. If one already exists, only a no-op on
  // the same domain is allowed here; moving domains goes through changeHostingEmailDomain.
  const existing = await db.emailSubscription.findFirst({
    where: { hostingAccountId: account.id, status: { not: "CANCELLED" } },
  });
  if (existing) {
    if (existing.domainName === domain) return { ok: true, subscriptionId: existing.id };
    return {
      error: `Bundled email is already set up on ${existing.domainName}. Move it to change the domain.`,
    };
  }

  const plan = await findBundledPlan(account.plan.mailboxes);
  if (!plan) {
    return {
      error:
        "Bundled email isn't configured for this plan yet. Please contact support — no charge, we'll switch it on.",
    };
  }

  const sub = await db.emailSubscription.create({
    data: {
      userId: account.userId,
      hostingAccountId: account.id,
      domainName: domain,
      emailPlanId: plan.id,
      status: "ACTIVE",
      autoRenew: true,
      expiresAt: account.expiresAt,
      // Free subdomain → we own the zone: managed + verified now (like an in-account
      // domain), records auto-published below. Real domain → external + unverified
      // until the customer publishes DNS and we confirm it.
      external: !free,
      verified: free,
      verifiedAt: free ? new Date() : null,
      verifyToken: free ? null : randomBytes(24).toString("hex"),
    },
  });

  await db.auditLog
    .create({
      data: {
        userId: account.userId,
        action: "hostingemail.setup",
        detail: `${domain} · bundled ${plan.name} (${plan.mailboxes} mailbox${plan.mailboxes === 1 ? "" : "es"}) via hosting ${account.plan.name}`,
      },
    })
    .catch(() => {});

  if (free) await autoConfigureFreeSubdomain(account.userId, domain);

  revalidatePath(`/dashboard/hosting/${accountId}`);
  revalidatePath("/dashboard/email");
  return { ok: true, subscriptionId: sub.id };
}

/**
 * Move the account's bundled email to a different domain on the account. Owner or
 * admin; blocked while impersonating. Refused while the current bundled domain has
 * mailboxes — those are keyed to the old address on the mail server, so moving the
 * domain out from under them would orphan live mail. Remove the mailboxes first.
 */
export async function changeHostingEmailDomain(
  accountId: string,
  domainName: string,
): Promise<HostingEmailResult> {
  const user = await requireUser();
  await assertNotImpersonating();

  const account = await loadAccount(accountId);
  if (!account) return { error: "Not found." };
  if (account.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };

  const bundled = await db.emailSubscription.findFirst({
    where: { hostingAccountId: account.id, status: { not: "CANCELLED" } },
    include: { mailboxes: { select: { id: true } } },
  });
  if (!bundled) return { error: "Set up bundled email first, then you can change its domain." };

  const resolved = await resolveTargetDomain(accountId, domainName, {
    ignoreSubscriptionId: bundled.id,
  });
  if ("error" in resolved) return { error: resolved.error };
  const { domain, free } = resolved;

  if (bundled.domainName === domain) return { ok: true, subscriptionId: bundled.id };

  if (bundled.mailboxes.length > 0) {
    return {
      error: `Remove the ${bundled.mailboxes.length} mailbox${bundled.mailboxes.length === 1 ? "" : "es"} on ${bundled.domainName} before moving email to another domain.`,
    };
  }

  await db.emailSubscription.update({
    where: { id: bundled.id },
    data: {
      domainName: domain,
      external: !free,
      verified: free,
      verifiedAt: free ? new Date() : null,
      verifyToken: free ? null : randomBytes(24).toString("hex"),
      // Drop the cached DKIM from the old domain — it belongs to the old zone.
      dkimRecord: null,
    },
  });

  await db.auditLog
    .create({
      data: {
        userId: account.userId,
        action: "hostingemail.movedomain",
        detail: `${bundled.domainName} → ${domain}`,
      },
    })
    .catch(() => {});

  if (free) await autoConfigureFreeSubdomain(account.userId, domain);

  revalidatePath(`/dashboard/hosting/${accountId}`);
  revalidatePath("/dashboard/email");
  return { ok: true, subscriptionId: bundled.id };
}

"use client";

import { useEffect, useState, useTransition } from "react";
import Link from "next/link";
import {
  getHostingEmailStatus,
  setupHostingEmail,
  changeHostingEmailDomain,
  type HostingEmailStatus,
  type HostingMailDomainOption,
  type HostingBundledEmail,
  type HostingMailbox,
} from "@/lib/hosting-email";
import {
  addMailbox,
  removeMailbox,
  revealMailboxPassword,
  resetMailboxPassword,
  retryMailboxProvision,
  checkEmailDeliverability,
} from "@/lib/actions-email-hosting";
import type { DeliverabilityReport, CheckStatus } from "@/lib/mail/deliverability";
import type { HostingAccountView } from "@/lib/actions-hosting";
import { EmailDnsSetup } from "@/components/customer/EmailDnsSetup";
import { Badge } from "@/components/ui/primitives";

/**
 * Bundled hosting email — PER-DOMAIN. The customer picks which of their account's
 * domains (primary / subdomain / addon) hosts their included mailboxes, instead of
 * being locked to the free setup subdomain. For a real (addon) domain we show the
 * MX/SPF/DKIM/DMARC records to publish + a deliverability check; for a free
 * subdomain we auto-configure the zone we control. The bundled subscription is a
 * normal EmailSubscription, so it's also fully manageable at /dashboard/email.
 */
export function EmailTab({ account }: { account: HostingAccountView }) {
  const [status, setStatus] = useState<HostingEmailStatus | null>(null);
  const [err, setErr] = useState<string | null>(null);

  function refresh() {
    getHostingEmailStatus(account.id)
      .then((s) => setStatus(s))
      .catch(() => setStatus({ error: "Couldn't load email status." }));
  }

  useEffect(() => {
    refresh();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [account.id]);

  if (!status) {
    return <div className="card py-12 text-center text-sm text-slate-400">Loading email…</div>;
  }
  if (status.error) {
    return <div className="card py-12 text-center text-sm text-red-300">{status.error}</div>;
  }

  const included = status.includedMailboxes ?? 0;
  const mailboxWord = included === 1 ? "mailbox" : "mailboxes";

  if (included <= 0) {
    return (
      <div className="card">
        <h2 className="mb-2 font-semibold">Email</h2>
        <p className="text-sm text-slate-400">
          Your <span className="text-white">{status.planName}</span> plan doesn&apos;t include any
          mailboxes. Upgrade your plan to add professional email.
        </p>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="card">
        <div className="mb-4 flex items-center justify-between gap-2">
          <h2 className="font-semibold">Email</h2>
          {status.bundled && (
            <Badge tone={status.bundled.free || status.bundled.verified ? "green" : "amber"}>
              {status.bundled.free
                ? "Managed by Nxeon"
                : status.bundled.verified
                  ? "Active"
                  : "Verify DNS"}
            </Badge>
          )}
        </div>

        <p className="text-sm text-slate-300">
          Your <span className="font-medium text-white">{status.planName}</span> plan includes{" "}
          <span className="font-medium text-white">{included} {mailboxWord}</span> — professional
          you@yourdomain email at no extra cost. Choose which of your domains hosts it.
        </p>

        {err && <div className="card mt-4 border-red-500/30 text-sm text-red-300">{err}</div>}

        {!status.bundled ? (
          <DomainPicker
            accountId={account.id}
            options={status.domainOptions ?? []}
            onDone={() => { setErr(null); refresh(); }}
            onError={setErr}
          />
        ) : (
          <BundledEmail
            accountId={account.id}
            bundled={status.bundled}
            options={status.domainOptions ?? []}
            onChanged={() => { setErr(null); refresh(); }}
            onError={setErr}
          />
        )}
      </div>
    </div>
  );
}

/* -------------------------------------------------------------- Domain pick --- */

function domainHint(o: HostingMailDomainOption): string {
  if (o.takenByOther) return "In use by another account";
  if (o.free) return "Free Nxeon subdomain — DNS configured automatically";
  return "You'll add MX/SPF/DKIM at your registrar, then verify";
}

function kindLabel(kind: string): string {
  return kind === "primary" ? "Primary" : kind === "subdomain" ? "Subdomain" : "Addon domain";
}

function DomainPicker({
  accountId,
  options,
  onDone,
  onError,
}: {
  accountId: string;
  options: HostingMailDomainOption[];
  onDone: () => void;
  onError: (e: string) => void;
}) {
  const selectable = options.filter((o) => !o.takenByOther && !o.hasEmail);
  const [chosen, setChosen] = useState(selectable[0]?.host ?? "");
  const [pending, start] = useTransition();

  function submit() {
    if (!chosen) {
      onError("Choose a domain for your email.");
      return;
    }
    start(async () => {
      const r = await setupHostingEmail(accountId, chosen);
      if (r.error) onError(r.error);
      else onDone();
    });
  }

  if (selectable.length === 0) {
    return (
      <p className="mt-4 text-sm text-slate-400">
        No available domain to host email yet. Add an addon domain or subdomain in the{" "}
        <span className="text-slate-300">Domains</span> tab, then come back here.
      </p>
    );
  }

  return (
    <div className="mt-4">
      <p className="mb-2 text-sm font-medium text-slate-200">Which domain should host your email?</p>
      <div className="space-y-2">
        {options.map((o) => {
          const disabled = o.takenByOther || o.hasEmail;
          const active = chosen === o.host;
          return (
            <label
              key={o.host}
              className={`flex cursor-pointer items-start gap-3 rounded-lg border px-3 py-2.5 transition-colors ${
                disabled
                  ? "cursor-not-allowed border-white/[0.04] opacity-50"
                  : active
                    ? "border-brand-400/50 bg-brand-500/[0.08]"
                    : "border-white/[0.06] hover:border-white/15"
              }`}
            >
              <input
                type="radio"
                name="mail-domain"
                className="mt-1"
                value={o.host}
                checked={active}
                disabled={disabled}
                onChange={() => setChosen(o.host)}
              />
              <span className="min-w-0">
                <span className="flex flex-wrap items-center gap-2">
                  <span className="font-mono text-sm text-white">{o.host}</span>
                  <Badge tone="slate">{kindLabel(o.kind)}</Badge>
                  {o.free && <Badge tone="green">Auto DNS</Badge>}
                </span>
                <span className="mt-0.5 block text-xs text-slate-500">{domainHint(o)}</span>
              </span>
            </label>
          );
        })}
      </div>
      <button type="button" className="btn-primary mt-4" disabled={pending || !chosen} onClick={submit}>
        {pending ? "Setting up…" : "Set up email on this domain"}
      </button>
    </div>
  );
}

/* ----------------------------------------------------------- Bundled email --- */

function BundledEmail({
  accountId,
  bundled,
  options,
  onChanged,
  onError,
}: {
  accountId: string;
  bundled: HostingBundledEmail;
  options: HostingMailDomainOption[];
  onChanged: () => void;
  onError: (e: string) => void;
}) {
  const [changing, setChanging] = useState(false);
  const canChange = bundled.mailboxes.length === 0;

  return (
    <div className="mt-4 space-y-4">
      <div className="flex flex-wrap items-center justify-between gap-2 rounded-lg border border-white/[0.06] bg-white/[0.02] px-3 py-2.5">
        <div className="min-w-0">
          <div className="flex flex-wrap items-center gap-2">
            <span className="font-mono text-sm text-white">{bundled.domainName}</span>
            <Badge tone="slate">{kindLabel(bundled.kind)}</Badge>
            {bundled.free ? (
              <Badge tone="green">Auto DNS</Badge>
            ) : bundled.verified ? (
              <Badge tone="green">Verified</Badge>
            ) : (
              <Badge tone="amber">Setup required</Badge>
            )}
          </div>
          <p className="mt-0.5 text-xs text-slate-500">
            {bundled.mailboxes.length}/{bundled.mailboxCap} mailboxes used
          </p>
        </div>
        <button
          type="button"
          className="btn-secondary py-1 text-xs"
          onClick={() => setChanging((v) => !v)}
        >
          {changing ? "Cancel" : "Change domain"}
        </button>
      </div>

      {changing && (
        <ChangeDomain
          accountId={accountId}
          current={bundled.domainName}
          options={options}
          canChange={canChange}
          mailboxCount={bundled.mailboxes.length}
          onChanged={() => { setChanging(false); onChanged(); }}
          onError={onError}
        />
      )}

      {/* Per-domain DNS. Free subdomain → we own the zone; real domain → the reusable
          registrar-records + verify panel. */}
      {bundled.free ? (
        <div className="rounded-lg border border-white/[0.06] bg-white/[0.02] px-3 py-2 text-xs text-slate-400">
          This is a free Nxeon subdomain, so its mail DNS (MX, SPF, DKIM, DMARC) is published in the zone
          we control — nothing for you to configure. Run the deliverability check below to confirm every
          record is live.
        </div>
      ) : (
        <EmailDnsSetup
          subscriptionId={bundled.subscriptionId}
          domainName={bundled.domainName}
          verified={bundled.verified}
        />
      )}

      <DeliverabilityCheck subscriptionId={bundled.subscriptionId} domainName={bundled.domainName} />

      <Mailboxes bundled={bundled} onChanged={onChanged} onError={onError} />

      <p className="text-xs text-slate-500">
        You can also manage these mailboxes from the full{" "}
        <Link href="/dashboard/email" className="text-brand-300 hover:underline">email dashboard</Link>.
      </p>
    </div>
  );
}

function ChangeDomain({
  accountId,
  current,
  options,
  canChange,
  mailboxCount,
  onChanged,
  onError,
}: {
  accountId: string;
  current: string;
  options: HostingMailDomainOption[];
  canChange: boolean;
  mailboxCount: number;
  onChanged: () => void;
  onError: (e: string) => void;
}) {
  const selectable = options.filter((o) => o.host !== current && !o.takenByOther && !o.hasEmail);
  const [chosen, setChosen] = useState(selectable[0]?.host ?? "");
  const [pending, start] = useTransition();

  if (!canChange) {
    return (
      <div className="rounded-lg border border-amber-500/30 bg-amber-500/[0.06] px-3 py-2 text-xs text-amber-300">
        Remove the {mailboxCount} mailbox{mailboxCount === 1 ? "" : "es"} on{" "}
        <span className="font-mono">{current}</span> before moving email to another domain — mailboxes
        are tied to their address on the mail server.
      </div>
    );
  }

  if (selectable.length === 0) {
    return (
      <div className="rounded-lg border border-white/[0.06] bg-white/[0.02] px-3 py-2 text-xs text-slate-400">
        No other available domain to move to. Add one in the Domains tab first.
      </div>
    );
  }

  function submit() {
    start(async () => {
      const r = await changeHostingEmailDomain(accountId, chosen);
      if (r.error) onError(r.error);
      else onChanged();
    });
  }

  return (
    <div className="rounded-lg border border-white/[0.06] bg-white/[0.02] p-3">
      <label className="label">Move email to</label>
      <select className="input" value={chosen} onChange={(e) => setChosen(e.target.value)}>
        {selectable.map((o) => (
          <option key={o.host} value={o.host}>
            {o.host} — {kindLabel(o.kind)}{o.free ? " (auto DNS)" : ""}
          </option>
        ))}
      </select>
      <button type="button" className="btn-primary mt-3 py-1.5 text-sm" disabled={pending} onClick={submit}>
        {pending ? "Moving…" : "Move email here"}
      </button>
    </div>
  );
}

/* --------------------------------------------------------------- Mailboxes --- */

function statusBadge(status: string): { tone: "green" | "amber" | "red" | "slate"; label: string } {
  switch (status) {
    case "ACTIVE":
      return { tone: "green", label: "Active" };
    case "FAILED":
      return { tone: "red", label: "Setup failed" };
    case "SUSPENDED":
      return { tone: "slate", label: "Suspended" };
    case "PROVISIONING":
      return { tone: "amber", label: "Provisioning" };
    default:
      return { tone: "slate", label: status || "Unknown" };
  }
}

function Mailboxes({
  bundled,
  onChanged,
  onError,
}: {
  bundled: HostingBundledEmail;
  onChanged: () => void;
  onError: (e: string) => void;
}) {
  const atLimit = bundled.mailboxes.length >= bundled.mailboxCap;

  return (
    <div>
      <h3 className="mb-2 text-sm font-semibold text-slate-200">
        Mailboxes <span className="font-normal text-slate-500">({bundled.mailboxes.length}/{bundled.mailboxCap})</span>
      </h3>
      {bundled.mailboxes.length === 0 ? (
        <p className="text-sm text-slate-500">No mailboxes yet — add your first below.</p>
      ) : (
        <div className="space-y-2">
          {bundled.mailboxes.map((m) => (
            <MailboxRow key={m.id} mailbox={m} onChanged={onChanged} onError={onError} />
          ))}
        </div>
      )}
      {!atLimit && (
        <AddMailboxForm
          subscriptionId={bundled.subscriptionId}
          domainName={bundled.domainName}
          onAdded={onChanged}
          onError={onError}
        />
      )}
      {atLimit && (
        <p className="mt-3 text-xs text-amber-400">
          Plan mailbox limit reached ({bundled.mailboxCap}). Remove one, or upgrade your plan for more.
        </p>
      )}
    </div>
  );
}

function AddMailboxForm({
  subscriptionId,
  domainName,
  onAdded,
  onError,
}: {
  subscriptionId: string;
  domainName: string;
  onAdded: () => void;
  onError: (e: string) => void;
}) {
  const [local, setLocal] = useState("");
  const [pending, start] = useTransition();

  function submit() {
    const v = local.trim();
    if (!v) { onError("Enter a mailbox name."); return; }
    start(async () => {
      const res = await addMailbox(subscriptionId, v);
      if (res?.error) onError(res.error);
      else if (res?.ok) { setLocal(""); onAdded(); }
    });
  }

  return (
    <div className="mt-3 flex flex-wrap items-end gap-2">
      <div className="min-w-0 flex-1">
        <label className="label">New mailbox</label>
        <div className="flex items-center">
          <input
            className="input rounded-r-none"
            value={local}
            onChange={(e) => setLocal(e.target.value)}
            placeholder="hello"
            onKeyDown={(e) => { if (e.key === "Enter") submit(); }}
          />
          <span className="rounded-r-lg border border-l-0 border-white/10 bg-white/[0.03] px-3 py-2 text-sm text-slate-400">
            @{domainName}
          </span>
        </div>
      </div>
      <button className="btn-primary" onClick={submit} disabled={pending}>
        {pending ? "Adding…" : "Add mailbox"}
      </button>
    </div>
  );
}

function MailboxRow({
  mailbox,
  onChanged,
  onError,
}: {
  mailbox: HostingMailbox;
  onChanged: () => void;
  onError: (e: string) => void;
}) {
  const [pending, start] = useTransition();
  const [pwPending, startPw] = useTransition();
  const [password, setPassword] = useState<string | null>(null);
  const [note, setNote] = useState<string | null>(null);
  const badge = statusBadge(mailbox.status);
  const usable = mailbox.status === "ACTIVE";
  const retryable = mailbox.status === "FAILED" || mailbox.status === "PROVISIONING";

  function retry() {
    startPw(async () => {
      const res = await retryMailboxProvision(mailbox.id);
      if (res?.error) onError(res.error);
      else onChanged();
    });
  }
  function reveal() {
    setNote(null);
    startPw(async () => {
      const res = await revealMailboxPassword(mailbox.id);
      if (res?.error) onError(res.error);
      else if (res?.password) { setPassword(res.password); setNote("Sign in with your full address."); }
    });
  }
  function resetPw() {
    if (!confirm(`Reset the password for ${mailbox.address}? The current one stops working.`)) return;
    setNote(null);
    startPw(async () => {
      const res = await resetMailboxPassword(mailbox.id);
      if (res?.error) onError(res.error);
      else if (res?.password) { setPassword(res.password); setNote("New password — copy it now."); }
    });
  }
  function remove() {
    if (!confirm(`Remove mailbox ${mailbox.address}?`)) return;
    start(async () => {
      const res = await removeMailbox(mailbox.id);
      if (res?.error) onError(res.error);
      else onChanged();
    });
  }

  return (
    <div className="rounded-lg border border-white/[0.06] px-3 py-2">
      <div className="flex flex-wrap items-center justify-between gap-2">
        <div className="flex flex-wrap items-center gap-2">
          <span className="font-mono text-sm text-white">{mailbox.address}</span>
          <Badge tone={badge.tone}>{badge.label}</Badge>
        </div>
        <div className="flex flex-wrap items-center gap-2">
          {usable && (
            <Link
              href={`/dashboard/mail?mailbox=${encodeURIComponent(mailbox.address)}`}
              className="btn-secondary py-1 text-xs"
            >
              Open inbox →
            </Link>
          )}
          {retryable && (
            <button className="btn-secondary py-1 text-xs" disabled={pwPending} onClick={retry}>
              {pwPending ? "…" : "Retry setup"}
            </button>
          )}
          <button className="btn-secondary py-1 text-xs" disabled={pwPending} onClick={reveal}>
            {password ? "Refresh password" : "Show password"}
          </button>
          <button className="btn-secondary py-1 text-xs" disabled={pwPending} onClick={resetPw}>
            Reset password
          </button>
          <button className="btn-danger py-1 text-xs" disabled={pending} onClick={remove}>
            Remove
          </button>
        </div>
      </div>
      {mailbox.status === "FAILED" && (
        <p className="mt-2 text-xs text-red-400">
          Not created on the mail server — mail to it is rejected. Press Retry setup.
        </p>
      )}
      {password && (
        <div className="mt-2 flex items-center gap-2 rounded-lg border border-white/[0.06] bg-white/[0.02] p-2">
          <code className="min-w-0 flex-1 truncate rounded bg-white/[0.04] px-2 py-1 font-mono text-xs text-slate-100">
            {password}
          </code>
          <button
            type="button"
            className="btn-secondary shrink-0 px-2 py-1 text-xs"
            onClick={() => navigator.clipboard?.writeText(password).catch(() => {})}
          >
            Copy
          </button>
          <button
            type="button"
            className="btn-secondary shrink-0 px-2 py-1 text-xs"
            onClick={() => { setPassword(null); setNote(null); }}
          >
            Hide
          </button>
        </div>
      )}
      {note && <p className="mt-1 text-[11px] text-slate-500">{note}</p>}
    </div>
  );
}

/* ---------------------------------------------------------- Deliverability --- */

const CHECK_TONE: Record<CheckStatus, "green" | "amber" | "red" | "slate"> = {
  pass: "green",
  warn: "amber",
  fail: "red",
  unknown: "slate",
};
const CHECK_LABEL: Record<CheckStatus, string> = {
  pass: "Pass",
  warn: "Warning",
  fail: "Fail",
  unknown: "Unknown",
};

function DeliverabilityCheck({
  subscriptionId,
  domainName,
}: {
  subscriptionId: string;
  domainName: string;
}) {
  const [report, setReport] = useState<DeliverabilityReport | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [pending, start] = useTransition();

  function run() {
    setError(null);
    start(async () => {
      const res = await checkEmailDeliverability(subscriptionId);
      if (res?.error) { setError(res.error); setReport(null); }
      else if (res?.report) setReport(res.report);
    });
  }

  const failing = report?.checks.filter((c) => c.status === "fail").length ?? 0;
  const warning = report?.checks.filter((c) => c.status === "warn").length ?? 0;
  const unknown = report?.checks.filter((c) => c.status === "unknown").length ?? 0;

  return (
    <div className="rounded-lg border border-white/[0.06] bg-white/[0.02] p-3">
      <div className="flex flex-wrap items-center justify-between gap-2">
        <div className="flex flex-wrap items-center gap-2">
          <span className="text-sm font-semibold text-white">Deliverability check</span>
          {report &&
            (failing > 0 ? (
              <Badge tone="red">{failing} problem{failing === 1 ? "" : "s"}</Badge>
            ) : unknown > 0 ? (
              <Badge tone="slate">Incomplete</Badge>
            ) : warning > 0 ? (
              <Badge tone="amber">{warning} warning{warning === 1 ? "" : "s"}</Badge>
            ) : (
              <Badge tone="green">All checks pass</Badge>
            ))}
        </div>
        <button className="btn-secondary py-1 text-xs" onClick={run} disabled={pending}>
          {pending ? "Checking DNS…" : report ? "Re-check" : "Check deliverability"}
        </button>
      </div>
      <p className="mt-2 text-xs text-slate-400">
        Checks what <span className="font-mono">{domainName}</span> actually publishes for MX, SPF, DKIM
        and DMARC. A failing row here is usually why mail lands in spam.
      </p>
      {error && (
        <div className="mt-2 rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-xs text-red-400">
          {error}
        </div>
      )}
      {report && (
        <div className="mt-3 space-y-2">
          {report.error && (
            <div className="rounded-lg border border-amber-500/30 bg-amber-500/10 px-3 py-2 text-xs text-amber-300">
              {report.error}
            </div>
          )}
          {report.checks.map((c) => (
            <div key={c.key} className="rounded-lg border border-white/[0.06] bg-white/[0.02] p-3">
              <div className="flex flex-wrap items-center gap-2">
                <Badge tone={CHECK_TONE[c.status]}>{CHECK_LABEL[c.status]}</Badge>
                <span className="text-sm font-medium text-slate-200">{c.label}</span>
                <span className="text-[11px] text-slate-500">
                  {c.type} · <span className="font-mono">{c.host}</span>
                </span>
              </div>
              <div className="mt-2 grid gap-2 sm:grid-cols-2">
                <div className="min-w-0">
                  <div className="text-[11px] uppercase tracking-wide text-slate-500">Found</div>
                  <code className="mt-0.5 block break-all rounded bg-white/[0.04] px-2 py-1 font-mono text-[11px] text-slate-200">
                    {c.observed || "— nothing published —"}
                  </code>
                </div>
                <div className="min-w-0">
                  <div className="text-[11px] uppercase tracking-wide text-slate-500">Expected</div>
                  <code className="mt-0.5 block break-all rounded bg-white/[0.04] px-2 py-1 font-mono text-[11px] text-slate-200">
                    {c.expected || "—"}
                  </code>
                </div>
              </div>
              <p
                className={`mt-2 text-xs ${
                  c.status === "fail"
                    ? "text-red-400"
                    : c.status === "warn"
                      ? "text-amber-400"
                      : c.status === "pass"
                        ? "text-emerald-300/80"
                        : "text-slate-400"
                }`}
              >
                {c.detail}
              </p>
            </div>
          ))}
          <p className="text-[11px] text-slate-500">
            {report.nameservers.length > 0 ? (
              <>
                Read directly from this domain&apos;s nameservers (
                <span className="font-mono">{report.nameservers.join(", ")}</span>).
              </>
            ) : (
              <>Couldn&apos;t reach this domain&apos;s nameservers, so no record could be read.</>
            )}{" "}
            Checked {new Date(report.checkedAt).toLocaleTimeString()}.
          </p>
        </div>
      )}
    </div>
  );
}

